import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0]=='n':
        return None
    r = T(int(arr[0]))
    q = deque([r]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def mirror(node):
    if node is None: return None
    return T(node.v, mirror(node.r), mirror(node.l))

def same(a, b):
    if a is None and b is None: return True
    if a is None or b is None: return False
    if a.v != b.v: return False
    return same(a.l, b.l) and same(a.r, b.r)

def is_symmetric_brute(root):
    return same(root, mirror(root))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1+n])
    print('true' if is_symmetric_brute(root) else 'false')

